using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 string StoryTitle(int i)=>new[]{"THE LAST HARVEST","WHAT THE YARD OWES","THE BEDS WE KEEP","THE BLACK LEDGER"}[i];
 void AddSettlementCampaignPanel(VBoxContainer b,SurvivorSettlement t){Button(b,StoryTitle(t.Index)+$" / CHAPTER {t.StoryStage} / DEVELOPMENT {t.Development}/3",()=>ShowSettlementStory(t.Index));Button(b,"TRADE / SETTLEMENT DEVELOPMENT AND YOUR REPUTATION",()=>ShowSettlementMarket(t.Index));}
 void ShowSettlementStory(int i){var t=Town(i);var b=Panel(StoryTitle(i));Text(b,$"{ExpeditionGame.SettlementNames[i]} / development {t.Development}/3 / foundation {t.Foundation} / future {t.Policy}\n"+t.StoryResult);void Act(string label,string op){Button(b,label,()=>{if(!CoopRequest("living",i+"|quest:"+op))LivingAction(i+"|quest:"+op);});}
  if(t.Fallen)Text(b,t.Destroyed?"Everyone is dead. The market is permanently lost.":"This community has evacuated. Its former services are gone.");else if(i==3){Text(b,Ledger.Outcome);switch(Ledger.State){case "unmet":Text(b,"Voss takes supplies from whoever cannot defend them. He offers high-end trade for obedience. Accepting starts a 30-minute shipment deadline; later failure or betrayal brings an armed raid against your own camp. Simply leaving now carries no contract penalty.");Act("ACCEPT SHIPMENT CONTRACT / CAMP BECOMES COLLATERAL","begin");break;case "debt":var at=SettlementMissionPoint(t);Text(b,$"Seized shipment at {at.X:0}, {at.Z:0}. Clear its infected guards and recover the crate. {Math.Max(0,Ledger.Due-game.World.Changes.Time)/60:0} active minutes remain.");LocationButton(b,"Seized shipment",at.X,at.Z,()=>ShowSettlementStory(i));if(Ledger.CacheTaken)Act("DELIVER CONFISCATED SHIPMENT / OPEN CITY MARKET","deliver");Act("BREAK CONTRACT / HOSTILITY AND CAMP RAID","refuse");break;case "offer":var target=game.World.Changes.Settlements.FirstOrDefault(s=>s.Index<2&&!s.Fallen);Text(b,target==null?"There are no surviving early settlements to target.":$"Voss wants {ExpeditionGame.SettlementNames[target.Index]} erased. Your standing there is {Standing("town/"+target.Index).Value}. At 20+, they trust you to infiltrate; otherwise you must assault. Both routes kill all five adults and permanently destroy its market. You may warn and fortify them instead, losing this faction's rewards and facing retaliation.");Act("ACCEPT EXTERMINATION ORDER / ROUTE LOCKS NOW","accept");Act("REFUSE VOSS / HOSTILITY AND CAMP RAID","refuse");break;case "assault":case "infiltration":case "burning":Text(b,Ledger.Outcome+$"\n{Math.Max(0,Ledger.Due-game.World.Changes.Time)/60:0} active minutes remain. Victims: {System.Numerics.BitOperations.PopCount((uint)Town(Ledger.Target).DeadResidents)}/5 dead.");Act("ABANDON THE ORDER / HOSTILITY AND CAMP RAID","refuse");break;default:Text(b,Ledger.Outcome);break;}}
  else{if(t.StoryDue>0&&t.StoryStage<4)Text(b,$"Deadline: {Math.Max(0,t.StoryDue-game.World.Changes.Time)/60:0} active minutes. No offline countdown. Choices are permanent; supplies alone cannot buy back a lost life or failed chapter.");switch(t.StoryStage){case 1:var at=SettlementMissionPoint(t);Text(b,new[]{"Tessa went looking for the old seed shipment. Iris wants her home; Jules says the camp cannot spare anyone.","Rafi took the last recovery truck out. Gus wants the parts; Nia insists the driver matters more.","Eli carried dressings through the infected ward. Ada needs him back; Rook wants to seal the route."}[i]+$"\nFind {ScoutName(i)} at {at.X:0}, {at.Z:0}. Clear the infected and give one bandage. Return here for the rebuilding choice.");LocationButton(b,ScoutName(i),at.X,at.Z,()=>ShowSettlementStory(i));Act("ABANDON THE SCOUT / THEY DIE, PROJECT CONTINUES","abandon");break;case 2:Text(b,"One project, not both. Civilian investment improves relief stock; fortification favors weapon trade. Complete within one active hour or this project declines permanently.");Act("BUILD CIVILIAN LIFELINE / 16 WOOD, 4 WATER, "+(4+i*4)+" ALLOY, "+i+" ELECTRONICS","care");Act("BUILD DEFENSE LINE / 24 WOOD, "+(10+i*5)+" ALLOY, "+i+" ELECTRONICS","fortify");break;case 3:Text(b,"Choose their future. Mutual aid sends supplies to another community and opens civilian specialties. Exclusive trade opens advanced weapons. Taking final payment leaves the settlement poorer.");Act("MUTUAL AID / 6 FOOD + 4 CLEAN WATER","commons");Act("EXCLUSIVE ARSENAL / "+(8+i*4)+" ALLOY + "+(2+i)+" ELECTRONICS","exclusive");Act("TAKE THE FINAL STOCK / PROFIT, DECLINE, TRUST -20","cashout");break;case 4:Text(b,"This story has its ending. You can maintain supplies and relationships, but the lost people and project choices remain.");break;}
   if(Ledger.Target==i&&Ledger.State is "assault" or "infiltration"){Text(b,"Voss has ordered this settlement erased. You can expose the order and pay for their survival. This closes the city market and redirects an armed retaliation to your camp.");Button(b,"WARN AND FORTIFY / 8 FOOD, 8 WATER, 20 WOOD, 12 ALLOY, 2 ELECTRONICS",()=>{if(!CoopRequest("living",i+"|quest:warn"))LivingAction(i+"|quest:warn");});}}
  Text(b,game.Notice);Button(b,"BACK",()=>ShowLivingPanel(i));
 }
 string MarketOffer(SurvivorSettlement t,int n)=>n==0?t.Index==0?"TRAIL PACK / 3 FOOD + 4 WATER":t.Index==1?"MAINTENANCE PACK / 4 ALLOY + 2 BANDAGES":t.Index==2?"MEDICAL PACK / 2 MEDICAL KITS":"CITY AMMUNITION / 24 RIFLE + 24 CARBINE":n==1?"SURVIVOR GEAR / TIER "+MarketCoatTier(t):n==2?"SPECIALIST WEAPON / "+ExpeditionGame.GunNames[MarketWeapon(t)]:"RELIEF RESERVE / 4 FOOD, 4 WATER, 2 MEDICAL KITS";
 int MarketCoatTier(SurvivorSettlement t)=>t.Index==3?5:Math.Min(t.Index+2,t.Development+1);
 int MarketWeapon(SurvivorSettlement t)=>t.Index==3?5:t.Index==0?t.Development>=3?19:18:t.Index==1?t.Development>=3?3:17:26;
 bool MarketAllowed(SurvivorSettlement t,int n){if(t.Fallen||t.Trust<0||Standing("town/"+t.Index).Value<0)return false;if(t.Index==2&&Fever.CitySeen&&!Fever.Redemption)return false;if(t.Index==3&&Ledger.State=="enemy")return false;return t.Development>=(n==0?1:n==1?2:3)&&(n!=2||t.Index==3||t.Foundation=="fortify"||t.Policy=="exclusive")&&(n!=3||t.Index!=3&&t.Policy=="commons");}
 void RestockSettlement(SurvivorSettlement t){t.MarketStock??=new[]{2,1,1,1};if(game.World.Changes.Time>=t.RestockAt){t.MarketStock=new[]{2,1,1,1};t.RestockAt=game.World.Changes.Time+900;}}
 void ShowSettlementMarket(int i){var t=Town(i);RestockSettlement(t);var b=Panel(ExpeditionGame.SettlementNames[i].ToUpperInvariant()+" / DEVELOPED TRADE");Text(b,$"Development {t.Development}/3 / your standing {Standing("town/"+i).Value}. Stock returns every 15 active minutes. Mature communities unlock better stock; a destroyed community never restocks. Research and legendary-heart requirements remain separate.");for(int n=0;n<4;n++){int offer=n;int cost=6+n*6+(i==3?8:0);Text(b,$"{MarketOffer(t,n)} / {cost} alloy + {n} electronics / stock {t.MarketStock[n]} / "+(MarketAllowed(t,n)?"AVAILABLE":"LOCKED / development, policy, story or reputation"));Button(b,"BARTER / "+MarketOffer(t,n),()=>{if(!CoopRequest("living",i+"|trade:"+offer))LivingAction(i+"|trade:"+offer);});}Button(b,"BACK",()=>ShowLivingPanel(i));}
 void SettlementTrade(SurvivorSettlement t,string op){if(!int.TryParse(op,out int n)||n<0||n>3)return;RestockSettlement(t);if(!MarketAllowed(t,n)||t.MarketStock[n]<=0){game.Notice="This stock is locked or sold out.";return;}int weapon=MarketWeapon(t);if(n==2&&(game.Craft.Weapons.Contains(weapon)||game.Craft.UnlockedTier<ExpeditionGame.GunTier(weapon)||game.WeaponGate(weapon)!="Ready")){game.Notice="Already owned, or discover this weapon's material tier and meet its equip gate first.";return;}int cost=6+n*6+(t.Index==3?8:0);if(!PaySettlementCost(0,0,0,cost,n))return;t.MarketStock[n]--;
  if(n==0){if(t.Index==0){game.Life.Food+=3;game.Craft.Water+=4;}if(t.Index==1){game.Craft.Materials[4]+=4;game.Life.Bandages+=2;}if(t.Index==2)game.Life.Medicine+=2;if(t.Index==3){game.Craft.GiveAmmo(1,24);game.Craft.GiveAmmo(2,24);}}
  if(n==1){int tier=MarketCoatTier(t);game.Profile.Items.Add(new ExpeditionRelic{Id="market/"+Guid.NewGuid(),Name=ExpeditionGame.SettlementNames[t.Index]+" survivor coat",Origin=StoryTitle(t.Index),Slot="chest",Level=tier,Armor=tier*9,Vitality=tier*3});}
  if(n==2){game.Craft.Weapons.Add(weapon);game.Life.WeaponQuality[weapon]=Math.Max(game.Life.WeaponQuality[weapon],15);}
  if(n==3){game.Life.Food+=4;game.Craft.Water+=4;game.Life.Medicine+=2;}game.Persist();game.Notice="Trade complete / "+MarketOffer(t,n);
 }
}
